#ifndef OOMPH_UPPER_LOWER_INTERACTION_HEADER
#define OOMPH_UPPER_LOWER_INTERACTION_HEADER

// Config header generated by autoconfig
#ifdef HAVE_CONFIG_H
#include <oomph-lib-config.h>
#endif

#include "../axisym_navier_stokes/axisym_fluid_traction_elements.h"
#include "../generic/element_with_external_element.h"
#include "lower_surface_lubrication_elements.h"
#include "upper_surface_lubrication_elements.h"

namespace oomph {
template <class LOWER_SURFACE_ELEMENT, class UPPER_SURFACE_ELEMENT>
class LowerInterfaceCoupledLubricationElement
    : public virtual LOWER_SURFACE_ELEMENT,
      public virtual ElementWithExternalElement {

public:
  /// Constructor: call the underlying constructors
  LowerInterfaceCoupledLubricationElement(FiniteElement *const &element_pt,
                                          const int &face_index)
      : LOWER_SURFACE_ELEMENT(element_pt, face_index),
        ElementWithExternalElement() {

    // There is one interaction: The applied pressure
    this->set_ninteraction(1);
  }

  /// Compute the element's residual vector and the Jacobian matrix.
  void fill_in_contribution_to_jacobian(Vector<double> &residuals,
                                        DenseMatrix<double> &jacobian) {
    // Get the analytical contribution from the basic Navier-Stokes element
    LOWER_SURFACE_ELEMENT::fill_in_contribution_to_jacobian(residuals,
                                                            jacobian);

    // Get the off-diagonal terms by finite differencing
    this->fill_in_jacobian_from_external_interaction_by_fd(residuals, jacobian);
  }

  /// Classify dof numbers as in underlying element
  void get_dof_numbers_for_unknowns(
      std::list<std::pair<unsigned long, unsigned>> &dof_lookup_list) const {
    // Call the underlying function
    LOWER_SURFACE_ELEMENT::get_dof_numbers_for_unknowns(dof_lookup_list);
  }

  /// Get number of dof types from underlying element
  unsigned ndof_types() const { return LOWER_SURFACE_ELEMENT::ndof_types(); }

  void describe_local_dofs(std::ostream &out,
                           const std::string &current_string) const {
    return LOWER_SURFACE_ELEMENT::describe_local_dofs(out, current_string);
  }

protected:
  void get_upper_surface(const unsigned &intpt, Vector<double> &x_out,
                         Vector<double> &u_out, double &pv_out,
                         Vector<double> &grad_pv_out) {

    // Set interaction index -- there's only one interaction...
    const unsigned interaction = 0;

    // Get a pointer to the external element that computes the
    // the pressure
    const UPPER_SURFACE_ELEMENT *upper_el_pt =
        dynamic_cast<UPPER_SURFACE_ELEMENT *>(
            external_element_pt(interaction, intpt));

    upper_el_pt->to_lower_surface(
        external_element_local_coord(interaction, intpt), x_out, u_out, pv_out,
        grad_pv_out);
  }
}; // end traction lubrication

template <class UPPER_SURFACE_ELEMENT, class LOWER_SURFACE_ELEMENT>
class UpperInterfaceCoupledLubricationElement
    : public virtual UPPER_SURFACE_ELEMENT,
      public virtual ElementWithExternalElement {
public:
  /// Constructor: call the underlying constructors
  UpperInterfaceCoupledLubricationElement(FiniteElement *const &element_pt,
                                          const int &face_index)
      : UPPER_SURFACE_ELEMENT(element_pt, face_index),
        ElementWithExternalElement() {

    // There is one interaction: The applied pressure
    this->set_ninteraction(1);
  }

  

  /// Compute the element's residual vector and the Jacobian matrix.
  void fill_in_contribution_to_jacobian(Vector<double> &residuals,
                                        DenseMatrix<double> &jacobian) {
    // Get the analytical contribution from the basic Navier-Stokes element
    UPPER_SURFACE_ELEMENT::fill_in_contribution_to_jacobian(residuals,
                                                            jacobian);

    // Get the off-diagonal terms by finite differencing
    this->fill_in_jacobian_from_external_interaction_by_fd(residuals, jacobian);
  }

  /// Classify dof numbers as in underlying element
  void get_dof_numbers_for_unknowns(
      std::list<std::pair<unsigned long, unsigned>> &dof_lookup_list) const {
    // Call the underlying function
    UPPER_SURFACE_ELEMENT::get_dof_numbers_for_unknowns(dof_lookup_list);
  }

  /// Get number of dof types from underlying element
  unsigned ndof_types() const { return UPPER_SURFACE_ELEMENT::ndof_types(); }

  void describe_local_dofs(std::ostream &out,
                           const std::string &current_string) const {
    return UPPER_SURFACE_ELEMENT::describe_local_dofs(out, current_string);
  }

  protected:

  /// Function to calculate impact surface
  void get_lower_surface(const unsigned &intpt,Vector<double> &x_out,
                        Vector<double> &n_out, Vector<double> &u_out, Vector<double> &dx_dt_out) {

    // Set interaction index -- there's only one interaction...
    const unsigned interaction = 0;

    // Get a pointer to the external surface element
    const LOWER_SURFACE_ELEMENT *lower_el_pt =
        dynamic_cast<LOWER_SURFACE_ELEMENT *>(
            external_element_pt(interaction, intpt));

     lower_el_pt->to_upper_surface(
        external_element_local_coord(interaction, intpt), x_out,n_out,u_out,dx_dt_out);
    
  }


};

} // namespace oomph

#endif